// Control de ingesta: cuenta los eventos de Cowrie (vía log-reader) en un intervalo cerrado,
// con 2 minutos de margen para que el pipeline termine de persistirlos.
const ahora = Date.now();
const desde = new Date(ahora - 20 * 60 * 1000), hasta = new Date(ahora - 2 * 60 * 1000);
const ev = await this.helpers.httpRequest({ method: 'GET', url: 'http://log-reader:9000/events?n=50000', json: true, timeout: 15000 });
if (!Array.isArray(ev)) throw new Error('log-reader no devolvió una lista de eventos');
const cowrie = ev.filter(e => e && e.timestamp && Date.parse(e.timestamp) >= +desde && Date.parse(e.timestamp) < +hasta).length;
return [{ json: { desde: desde.toISOString(), hasta: hasta.toISOString(), cowrie } }];

const c = $('Leer log de Cowrie').first().json;
const b = $input.first().json;
const base = Number(b.base), viejos = Number(b.sin_procesar_viejos);
const alertas = [];
if (c.cowrie > base) alertas.push(`ingesta: ${c.cowrie} eventos en Cowrie y ${base} en la base entre ${c.desde} y ${c.hasta}`);
if (viejos > 0) alertas.push(`extracción: ${viejos} eventos sin procesar creados hace más de 35 minutos`);
return alertas.map(error => ({ json: { error } }));
